package ae.proto;

import static org.junit.jupiter.api.Assertions.*;

import java.io.ByteArrayOutputStream;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.jupiter.api.Test;

class FuzzTest {
    static final MessageType ALL = CodecTest.S.message("All");
    static final MessageType T1 = CodecTest.S.message("Test1");
    static final BigInteger TWO64 = BigInteger.ONE.shiftLeft(64);

    // ---- reference encoder: BigInteger varints, written independently of Varint ----

    static void refVarint(ByteArrayOutputStream o, BigInteger u) {
        BigInteger low = BigInteger.valueOf(0x7f);
        while (u.compareTo(low) > 0) {
            o.write(u.and(low).intValue() | 0x80);
            u = u.shiftRight(7);
        }
        o.write(u.intValue());
    }

    /** two's complement view of a signed value as an unsigned 64-bit number. */
    static BigInteger u64(long v) {
        BigInteger b = BigInteger.valueOf(v);
        return v < 0 ? b.add(TWO64) : b;
    }

    /** zigzag from its definition: non-negative n -> 2n, negative n -> -2n-1. */
    static BigInteger zz(long v) {
        BigInteger b = BigInteger.valueOf(v);
        return v >= 0 ? b.shiftLeft(1) : b.negate().shiftLeft(1).subtract(BigInteger.ONE);
    }

    static void refTag(ByteArrayOutputStream o, int field, int wire) {
        refVarint(o, BigInteger.valueOf(((long) field << 3) | wire));
    }

    static void refLe(ByteArrayOutputStream o, long v, int n) {
        for (int i = 0; i < n; i++) o.write((int) ((v >>> (8 * i)) & 0xff));
    }

    static void refLen(ByteArrayOutputStream o, int field, byte[] payload) {
        refTag(o, field, 2);
        refVarint(o, BigInteger.valueOf(payload.length));
        o.writeBytes(payload);
    }

    static long randLong(Random r) {
        return r.nextLong() >> r.nextInt(64);
    }

    static String randString(Random r) {
        StringBuilder sb = new StringBuilder();
        int n = r.nextInt(6);
        for (int i = 0; i < n; i++) {
            switch (r.nextInt(4)) {
                case 0 -> sb.append((char) ('a' + r.nextInt(26)));
                case 1 -> sb.append((char) (0xa0 + r.nextInt(0x500)));
                case 2 -> sb.append((char) (0x4e00 + r.nextInt(100)));
                default -> sb.appendCodePoint(0x1F600 + r.nextInt(50));
            }
        }
        return sb.toString();
    }

    static boolean pick(Random r) {
        return r.nextInt(3) == 0;
    }

    /** Random All message plus the exact bytes the reference encoder expects (ascending field order). */
    static Msg gen(Random r, ByteArrayOutputStream ref) {
        Msg m = Msg.of(ALL);
        if (pick(r)) {
            int v = (int) randLong(r);
            m = m.set("i32", v);
            refTag(ref, 1, 0);
            refVarint(ref, u64(v)); // int32 is sign-extended to 64 bits
        }
        if (pick(r)) {
            long v = randLong(r);
            m = m.set("i64", v);
            refTag(ref, 2, 0);
            refVarint(ref, u64(v));
        }
        if (pick(r)) {
            long v = r.nextLong() & 0xFFFFFFFFL;
            m = m.set("u32", v);
            refTag(ref, 3, 0);
            refVarint(ref, BigInteger.valueOf(v));
        }
        if (pick(r)) {
            long v = randLong(r);
            m = m.set("u64", v);
            refTag(ref, 4, 0);
            refVarint(ref, u64(v));
        }
        if (pick(r)) {
            int v = (int) randLong(r);
            m = m.set("s32", v);
            refTag(ref, 5, 0);
            refVarint(ref, zz(v));
        }
        if (pick(r)) {
            long v = randLong(r);
            m = m.set("s64", v);
            refTag(ref, 6, 0);
            refVarint(ref, zz(v));
        }
        if (pick(r)) {
            boolean v = r.nextBoolean();
            m = m.set("b", v);
            refTag(ref, 7, 0);
            ref.write(v ? 1 : 0);
        }
        if (pick(r)) {
            long v = r.nextLong() & 0xFFFFFFFFL;
            m = m.set("f32", v);
            refTag(ref, 8, 5);
            refLe(ref, v, 4);
        }
        if (pick(r)) {
            long v = r.nextLong();
            m = m.set("f64", v);
            refTag(ref, 9, 1);
            refLe(ref, v, 8);
        }
        if (pick(r)) {
            int v = r.nextInt();
            m = m.set("sf32", v);
            refTag(ref, 10, 5);
            refLe(ref, v, 4);
        }
        if (pick(r)) {
            long v = r.nextLong();
            m = m.set("sf64", v);
            refTag(ref, 11, 1);
            refLe(ref, v, 8);
        }
        if (pick(r)) {
            float v = Float.intBitsToFloat(r.nextInt());
            if (Float.isNaN(v)) v = 1.5f;
            m = m.set("fl", v);
            refTag(ref, 12, 5);
            refLe(ref, Float.floatToIntBits(v), 4);
        }
        if (pick(r)) {
            double v = r.nextGaussian() * 1e6;
            m = m.set("db", v);
            refTag(ref, 13, 1);
            refLe(ref, Double.doubleToLongBits(v), 8);
        }
        if (pick(r)) {
            String v = randString(r);
            m = m.set("s", v);
            refLen(ref, 14, v.getBytes(StandardCharsets.UTF_8));
        }
        if (pick(r)) {
            byte[] v = new byte[r.nextInt(5)];
            r.nextBytes(v);
            m = m.set("by", Bytes.of(v));
            refLen(ref, 15, v);
        }
        if (pick(r)) {
            int a = (int) randLong(r);
            m = m.set("sub", Msg.of(T1).set("a", a));
            ByteArrayOutputStream inner = new ByteArrayOutputStream();
            refTag(inner, 1, 0);
            refVarint(inner, u64(a));
            refLen(ref, 16, inner.toByteArray());
        }
        int n = r.nextInt(4);
        if (n > 0) { // packed
            ByteArrayOutputStream inner = new ByteArrayOutputStream();
            for (int i = 0; i < n; i++) {
                int v = (int) randLong(r);
                m = m.add("ri", v);
                refVarint(inner, u64(v));
            }
            refLen(ref, 17, inner.toByteArray());
        }
        n = r.nextInt(3);
        for (int i = 0; i < n; i++) { // unpacked, one field per element
            String v = randString(r);
            m = m.add("rs", v);
            refLen(ref, 18, v.getBytes(StandardCharsets.UTF_8));
        }
        n = r.nextInt(3);
        for (int i = 0; i < n; i++) {
            ByteArrayOutputStream inner = new ByteArrayOutputStream();
            if (r.nextBoolean()) {
                int a = r.nextInt();
                m = m.add("rm", Msg.of(T1).set("a", a));
                refTag(inner, 1, 0);
                refVarint(inner, u64(a));
            } else {
                m = m.add("rm", Msg.of(T1));
            }
            refLen(ref, 19, inner.toByteArray());
        }
        n = r.nextInt(3);
        if (n > 0) {
            ByteArrayOutputStream inner = new ByteArrayOutputStream();
            for (int i = 0; i < n; i++) {
                double v = r.nextDouble();
                m = m.add("rd", v);
                refLe(inner, Double.doubleToLongBits(v), 8);
            }
            refLen(ref, 20, inner.toByteArray());
        }
        n = r.nextInt(4);
        if (n > 0) {
            ByteArrayOutputStream inner = new ByteArrayOutputStream();
            for (int i = 0; i < n; i++) {
                boolean v = r.nextBoolean();
                m = m.add("rb", v);
                inner.write(v ? 1 : 0);
            }
            refLen(ref, 21, inner.toByteArray());
        }
        return m;
    }

    @Test
    void encoderMatchesIndependentReferenceAndDecodeInvertsIt() {
        Random r = new Random(2026);
        int nonEmpty = 0;
        for (int i = 0; i < 3000; i++) {
            ByteArrayOutputStream ref = new ByteArrayOutputStream();
            Msg m = gen(r, ref);
            byte[] bytes = Codec.encode(m);
            assertArrayEquals(ref.toByteArray(), bytes, "case " + i + " " + m);
            Msg back = Codec.decode(ALL, bytes);
            assertEquals(m, back, "case " + i);
            assertArrayEquals(bytes, Codec.encode(back), "canonical re-encode " + i);
            if (bytes.length > 0) nonEmpty++;
        }
        assertTrue(nonEmpty > 2900, "generator produced mostly empty messages: " + nonEmpty);
    }

    @Test
    void everyTruncationAndEveryByteFlipEitherDecodesOrThrowsDecodeException() {
        Random r = new Random(99);
        int decodedAfterFlip = 0, rejectedAfterFlip = 0, rejectedPrefix = 0;
        for (int i = 0; i < 150; i++) {
            Msg m = gen(r, new ByteArrayOutputStream());
            byte[] bytes = Codec.encode(m);
            for (int cut = 0; cut < bytes.length; cut++) {
                byte[] prefix = java.util.Arrays.copyOf(bytes, cut);
                try {
                    Msg got = Codec.decode(ALL, prefix);
                    assertEquals(got, Codec.decode(ALL, Codec.encode(got)), "stable re-decode");
                } catch (DecodeException e) {
                    rejectedPrefix++;
                    assertTrue(e.getOffset() >= 0 && e.getOffset() <= cut, e.getOffset() + " > " + cut);
                }
            }
            for (int pos = 0; pos < bytes.length; pos++) {
                byte[] bad = bytes.clone();
                bad[pos] ^= (byte) (1 << r.nextInt(8));
                try {
                    Msg got = Codec.decode(ALL, bad);
                    decodedAfterFlip++;
                    assertEquals(got, Codec.decode(ALL, Codec.encode(got)), "stable re-decode after flip");
                } catch (DecodeException e) {
                    rejectedAfterFlip++;
                    assertTrue(e.getOffset() >= 0 && e.getOffset() <= bad.length);
                }
            }
        }
        // both outcomes must occur, otherwise the fuzz is not exercising the decoder
        assertTrue(rejectedPrefix > 100, "prefix rejections " + rejectedPrefix);
        assertTrue(decodedAfterFlip > 100, "flips that still decode " + decodedAfterFlip);
        assertTrue(rejectedAfterFlip > 100, "flips that are rejected " + rejectedAfterFlip);
    }

    @Test
    void randomGarbageNeverThrowsAnythingButDecodeException() {
        Random r = new Random(5);
        List<Integer> sizes = new ArrayList<>();
        for (int i = 0; i < 5000; i++) {
            byte[] junk = new byte[r.nextInt(40)];
            r.nextBytes(junk);
            try {
                Codec.decode(ALL, junk);
                sizes.add(junk.length);
            } catch (DecodeException expected) {
                assertTrue(expected.getOffset() >= 0);
            }
        }
        assertFalse(sizes.isEmpty(), "some garbage should decode (e.g. empty input)");
    }
}

tests.src/test/java/ae/proto/VarintTest.java:
package ae.proto;

import static org.junit.jupiter.api.Assertions.*;

import java.math.BigInteger;
import java.util.HexFormat;
import java.util.Random;
import org.junit.jupiter.api.Test;

class VarintTest {
    static byte[] hex(String s) {
        return HexFormat.of().parseHex(s.replace(" ", ""));
    }

    @Test
    void literalEncodings() {
        assertArrayEquals(hex("00"), Varint.encode(0));
        assertArrayEquals(hex("01"), Varint.encode(1));
        assertArrayEquals(hex("7f"), Varint.encode(127));
        assertArrayEquals(hex("80 01"), Varint.encode(128));
        assertArrayEquals(hex("96 01"), Varint.encode(150));
        assertArrayEquals(hex("ac 02"), Varint.encode(300));
        assertArrayEquals(hex("ff ff ff ff ff ff ff ff ff 01"), Varint.encode(-1L));
        assertArrayEquals(hex("ff ff ff ff ff ff ff ff 7f"), Varint.encode(Long.MAX_VALUE));
        assertArrayEquals(hex("80 80 80 80 80 80 80 80 80 01"), Varint.encode(Long.MIN_VALUE));
    }

    @Test
    void sizeMatchesEncodeAtEveryBitLength() {
        for (int bits = 0; bits < 64; bits++) {
            long v = bits == 0 ? 0 : (1L << bits) - 1; // bits ones
            // bits ones need ceil(bits/7) bytes, at least 1 (comment table: 7->1, 8->2, 14->2, 15->3, 63->9)
            int expected = Math.max(1, (bits + 6) / 7);
            assertEquals(expected, Varint.encode(v).length, "bits=" + bits);
            assertEquals(expected, Varint.size(v), "size bits=" + bits);
            long w = 1L << bits; // single bit at position bits -> bits+1 significant bits
            assertEquals((bits + 7) / 7, Varint.size(w), "single bit " + bits);
        }
        assertEquals(10, Varint.size(-1L));
    }

    @Test
    void readReturnsValueAndNextPosition() {
        byte[] b = hex("aa 96 01 05");
        Varint.Read r = Varint.read(b, 1, b.length);
        assertEquals(150, r.value());
        assertEquals(3, r.next());
        assertEquals(5, Varint.read(b, 3, b.length).value());
    }

    @Test
    void paddedVarintIsAccepted() {
        Varint.Read r = Varint.read(hex("81 80 00"), 0, 3);
        assertEquals(1, r.value());
        assertEquals(3, r.next());
    }

    @Test
    void readRespectsEndNotArrayLength() {
        byte[] b = hex("96 01");
        DecodeException e = assertThrows(DecodeException.class, () -> Varint.read(b, 0, 1));
        assertTrue(e.getMessage().contains("truncated"), e.getMessage());
        assertEquals(0, e.getOffset());
    }

    @Test
    void truncatedAndEmptyAreErrors() {
        assertThrows(DecodeException.class, () -> Varint.read(new byte[0], 0, 0));
        assertThrows(DecodeException.class, () -> Varint.read(hex("80 80"), 0, 2));
    }

    @Test
    void tenthByteAboveOneOverflows() {
        DecodeException e = assertThrows(DecodeException.class,
                () -> Varint.read(hex("ff ff ff ff ff ff ff ff ff 02"), 0, 10));
        assertTrue(e.getMessage().contains("overflow"), e.getMessage());
        // control: differs only by the 10th byte
        assertEquals(-1L, Varint.read(hex("ff ff ff ff ff ff ff ff ff 01"), 0, 10).value());
    }

    @Test
    void eleventhByteOverflows() {
        assertThrows(DecodeException.class,
                () -> Varint.read(hex("80 80 80 80 80 80 80 80 80 80 00"), 0, 11));
    }

    @Test
    void zigzagLiterals() {
        assertEquals(0, Varint.zigzag32(0));
        assertEquals(1, Varint.zigzag32(-1));
        assertEquals(2, Varint.zigzag32(1));
        assertEquals(3, Varint.zigzag32(-2));
        assertEquals(4294967294L, Varint.zigzag32(Integer.MAX_VALUE));
        assertEquals(4294967295L, Varint.zigzag32(Integer.MIN_VALUE));
        assertEquals(0, Varint.zigzag64(0));
        assertEquals(1, Varint.zigzag64(-1));
        assertEquals(-2L, Varint.zigzag64(Long.MAX_VALUE)); // 0xFFFF...FE
        assertEquals(-1L, Varint.zigzag64(Long.MIN_VALUE)); // 0xFFFF...FF
    }

    @Test
    void zigzagRoundTripsAtExtremes() {
        int[] ints = {0, 1, -1, 2, -2, Integer.MAX_VALUE, Integer.MIN_VALUE, Integer.MIN_VALUE + 1};
        for (int i : ints) assertEquals(i, Varint.unzigzag32(Varint.zigzag32(i)));
        long[] longs = {0, 1, -1, Long.MAX_VALUE, Long.MIN_VALUE, Long.MIN_VALUE + 1};
        for (long l : longs) assertEquals(l, Varint.unzigzag64(Varint.zigzag64(l)));
    }

    @Test
    void randomEncodingsMatchBigIntegerGroups() {
        Random rnd = new Random(7);
        for (int i = 0; i < 20000; i++) {
            long v = rnd.nextLong() >>> rnd.nextInt(64);
            BigInteger u = new BigInteger(Long.toUnsignedString(v));
            byte[] expected = new byte[Varint.size(v)];
            for (int k = 0; k < expected.length; k++) {
                int group = u.shiftRight(7 * k).and(BigInteger.valueOf(0x7f)).intValue();
                expected[k] = (byte) (group | (k < expected.length - 1 ? 0x80 : 0));
            }
            byte[] actual = Varint.encode(v);
            assertArrayEquals(expected, actual, Long.toUnsignedString(v));
            assertEquals(v, Varint.read(actual, 0, actual.length).value());
            // the group count itself comes from the bit length of the BigInteger
            assertEquals(Math.max(1, (u.bitLength() + 6) / 7), actual.length);
        }
    }
}

tests.src/test/java/ae/proto/SchemaTest.java:
package ae.proto;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import org.junit.jupiter.api.Test;

class SchemaTest {
    static final String GOOD = """
            // a comment
            message Outer {
              int32 a = 1;   // trailing comment
              repeated sint64 xs = 4;
              Inner in = 3;
              repeated Outer kids = 9;
            }
            message Inner { string s = 2; bytes raw = 1; bool flag = 7; }
            """;

    @Test
    void parsesMessagesFieldsAndForwardAndRecursiveReferences() {
        Schema s = Schema.parse(GOOD);
        assertEquals(List.of("Outer", "Inner"), s.messageNames());
        MessageType outer = s.message("Outer");
        assertEquals("Outer", outer.name());
        assertEquals(List.of(1, 3, 4, 9), outer.fields().stream().map(Field::number).toList());
        Field xs = outer.field("xs");
        assertEquals(4, xs.number());
        assertEquals(Kind.SINT64, xs.kind());
        assertTrue(xs.repeated());
        assertNull(xs.message());
        assertSame(s.message("Inner"), outer.field(3).message());
        assertSame(outer, outer.field("kids").message());
        assertNull(outer.field(2));
        assertNull(outer.field("nope"));
    }

    @Test
    void allScalarKindsParse() {
        String text = "message M { int32 a=1; int64 b=2; uint32 c=3; uint64 d=4; sint32 e=5; sint64 f=6;"
                + " bool g=7; fixed32 h=8; fixed64 i=9; sfixed32 j=10; sfixed64 k=11; float l=12;"
                + " double m=13; string n=14; bytes o=15; }";
        MessageType m = Schema.parse(text).message("M");
        assertEquals(15, m.fields().size());
        assertEquals(Kind.SFIXED64, m.field("k").kind());
        assertEquals(Kind.BYTES, m.field("o").kind());
    }

    @Test
    void missingMessageLookupThrows() {
        assertThrows(IllegalArgumentException.class, () -> Schema.parse(GOOD).message("Nope"));
    }

    private static String err(String text) {
        return assertThrows(SchemaException.class, () -> Schema.parse(text)).getMessage();
    }

    @Test
    void duplicateFieldNumberReportsLine() {
        String m = err("message A {\n int32 a = 1;\n int32 b = 1;\n}");
        assertTrue(m.startsWith("line 3:"), m);
        assertTrue(m.contains("duplicate field number"), m);
    }

    @Test
    void duplicateFieldNameReportsLine() {
        String m = err("message A {\n int32 a = 1;\n int64 a = 2;\n}");
        assertTrue(m.startsWith("line 3:") && m.contains("duplicate field name"), m);
    }

    @Test
    void duplicateMessage() {
        String m = err("message A {}\nmessage A {}");
        assertTrue(m.startsWith("line 2:") && m.contains("duplicate message"), m);
    }

    @Test
    void unknownTypeReportsLineOfField() {
        String m = err("message A {\n Missing x = 1;\n}");
        assertTrue(m.startsWith("line 2:") && m.contains("unknown type Missing"), m);
    }

    @Test
    void numberRange() {
        assertTrue(err("message A { int32 a = 0; }").contains("field number"));
        assertTrue(err("message A { int32 a = 536870912; }").contains("field number"));
        assertTrue(err("message A { int32 a = 19000; }").contains("reserved"));
        assertTrue(err("message A { int32 a = 19999; }").contains("reserved"));
        // controls just outside / at the edges are fine
        Schema.parse("message A { int32 a = 18999; int32 b = 20000; int32 c = 1; int32 d = 536870911; }");
    }

    @Test
    void syntaxErrors() {
        assertTrue(err("message A { int32 a = 1 }").startsWith("line 1:"));
        assertTrue(err("message { int32 a = 1; }").contains("message name"));
        assertTrue(err("message A { int32 a = 1;").contains("end of input"));
        assertTrue(err("message A { int32 a = x; }").contains("number"));
        assertTrue(err("int32 a = 1;").contains("message"));
    }

    @Test
    void emptySchemaAndEmptyMessageAreValid() {
        assertTrue(Schema.parse("// nothing\n").messageNames().isEmpty());
        assertTrue(Schema.parse("message E {}").message("E").fields().isEmpty());
    }
}

